-- 検定詳細ページ（/subjects/[slug]）のデータ。
-- Supabase の管理画面 → SQL Editor に貼り付けて実行してください。

create table if not exists public.subjects (
  slug text primary key,
  name text not null,
  full_name text not null,
  category text not null,
  organizer text not null,
  -- カード・見出しの色（トップページと同じ sakura/lemon/sky/mint のパステル4色）
  tone text not null default 'sakura',
  catch_copy text not null,
  overview text not null,
  -- 基本情報テーブル。[{ "label": "実施回数", "value": "年2回" }, ...] の形
  basics jsonb not null default '[]'::jsonb,
  -- 商業検定ラボでの対策内容。文字列の配列
  training jsonb not null default '[]'::jsonb,
  pricing_lead text not null default '',
  -- 級ごとの受講料。[{ "grade": "3級", "price": "3,100", "unit": "円 / 1時間" }, ...] の形
  pricing_plans jsonb not null default '[]'::jsonb,
  -- 追加オプション（無ければ空配列）。[{ "name": ..., "price": ..., "description": ... }, ...] の形
  pricing_options jsonb not null default '[]'::jsonb,
  pricing_note text not null default '',
  -- つまずきポイント。[{ "problem": ..., "solution": ... }, ...] の形
  struggles jsonb not null default '[]'::jsonb,
  updated_at timestamptz not null default now()
);

alter table public.subjects enable row level security;

-- 検定詳細ページはサイトの公開コンテンツなので、誰でも閲覧できる
drop policy if exists "誰でも検定ページを閲覧できる" on public.subjects;
create policy "誰でも検定ページを閲覧できる"
  on public.subjects
  for select
  to anon, authenticated
  using (true);

-- 更新は管理者だけ（Step 4 の要件は編集のみのため、追加・削除のポリシーは設けていない）
drop policy if exists "管理者は検定ページを更新できる" on public.subjects;
create policy "管理者は検定ページを更新できる"
  on public.subjects
  for update
  to authenticated
  using (is_admin())
  with check (is_admin());

-- これまで subjects.ts に書いていた6件をDBへ移行する
insert into public.subjects
  (slug, name, full_name, category, organizer, tone, catch_copy, overview, basics, training, pricing_lead, pricing_plans, pricing_options, pricing_note, struggles)
values
  ('zensho-boki', '簿記実務検定', '全国商業高等学校協会主催 簿記実務検定試験', '全商検定', '公益財団法人 全国商業高等学校協会', 'sakura', '仕訳が分かれば、簿記はいっきに面白くなる。', '商業高校で最初に取り組む人が多い、全商検定の中心となる検定です。3級で簿記の基本原理と個人企業の決算を、2級で株式会社会計を、1級で会計と原価計算を扱います。1級を取得すると進学・就職の場面でそのまま評価につながるため、在学中に1級合格まで目指す価値の大きい検定です。', '[{"label":"実施回数","value":"年2回（1月・6月）"},{"label":"級","value":"3級／2級／1級（会計・原価計算）"},{"label":"試験時間","value":"各科目 1時間30分"},{"label":"合格基準","value":"100点満点中 70点以上"},{"label":"1級の扱い","value":"「会計」「原価計算」の2科目に合格すると1級合格となる"}]'::jsonb, '["受験する級の出題範囲を分解し、検定日から逆算した学習計画を作成","「なぜその仕訳になるのか」を仕組みから説明し、暗記に頼らない理解へ","頻出の仕訳パターンを繰り返し演習して、手が勝手に動く状態まで定着","過去問を本番と同じ時間配分で解き、解き終わらない原因を特定","間違えた問題を分類し、同じ失点を繰り返さないための復習リストを作成"]'::jsonb, '1対1の個別指導の料金です。受験する級に合わせて選べます。', '[{"grade":"3級","price":"3,100","unit":"円 / 1時間"},{"grade":"2級","price":"3,200","unit":"円 / 1時間"},{"grade":"1級","price":"3,400","unit":"円 / 1時間"}]'::jsonb, '[]'::jsonb, '※ 受講回数やスケジュールは相談しながら決められます。詳しくは無料体験のときにご案内します。', '[{"problem":"仕訳は解けるのに、精算表・決算になると点が取れない","solution":"決算整理を「どの勘定がどう動くか」の流れで整理し直します。1問ずつ手順を声に出して確認しながら解くことで、途中でつまずく箇所が特定できます。"},{"problem":"1級になって急に難しく感じ、手が止まってしまう","solution":"会計と原価計算では必要な考え方が違います。原価計算は計算パターンの型を先に固め、会計は理論の理解を優先するなど、科目ごとに攻め方を変えて進めます。"},{"problem":"時間内に最後まで解き終わらない","solution":"大問ごとの目標時間を決めて演習します。捨てる問題と確実に取る問題の判断を練習しておくと、本番で焦らず得点を積み上げられます。"}]'::jsonb),
  ('business-joho', '情報処理検定（ビジネス情報）', '全国商業高等学校協会主催 情報処理検定試験（ビジネス情報部門）', '全商検定', '公益財団法人 全国商業高等学校協会', 'sky', '表計算は、関数を覚えるより「型」を覚える。', 'パソコンを使う仕事の基礎力を証明する検定です。3級・2級で表計算ソフトの基本操作と情報の知識を身につけ、1級ビジネス情報部門では表計算の高度な活用やデータベースの知識まで広がります。筆記と実技の両方があるため、知識と操作をバランスよく仕上げる必要があります。', '[{"label":"実施回数","value":"年1回"},{"label":"級","value":"3級／2級／1級（ビジネス情報部門）"},{"label":"出題形式","value":"筆記＋実技（表計算ソフトの操作）"},{"label":"合格基準","value":"筆記・実技ともに規定の得点以上"}]'::jsonb, '["実技で使う関数を「どんな場面で使うか」の型で整理し、迷わず選べる状態に","筆記の用語は分野ごとにまとめて覚え、暗記の負担を減らす","画面を共有しながら操作手順を確認し、つまずいた瞬間にその場で修正","過去問を本番と同じ制限時間で解き、時間内に仕上げる練習","間違えた問題を分類し、同じ失点を繰り返さないための復習リストを作成"]'::jsonb, '1対1の個別指導の料金です。受験する級に合わせて選べます。', '[{"grade":"3級","price":"3,100","unit":"円 / 1時間"},{"grade":"2級","price":"3,200","unit":"円 / 1時間"},{"grade":"1級","price":"3,400","unit":"円 / 1時間"}]'::jsonb, '[]'::jsonb, '※ 受講回数やスケジュールは相談しながら決められます。詳しくは無料体験のときにご案内します。', '[{"problem":"関数は知っているのに、実技になると手が止まる","solution":"「問題文のどこを読んで、どの関数を選ぶか」の判断手順を型にします。手順どおりに解く練習を重ねると、初見の問題でも迷わず着手できるようになります。"},{"problem":"筆記の用語がなかなか覚えられない","solution":"用語を単体で暗記せず、仕組みの流れの中で関連づけて整理します。似た用語をまとめて比較すると、選択肢で迷う場面が減ります。"},{"problem":"自宅にパソコンがなくて実技の練習ができない","solution":"学校のパソコンで進める実技と、スマートフォンでも進められる筆記対策を切り分けて計画します。限られた練習時間を実技に集中させられます。"}]'::jsonb),
  ('programming', '情報処理検定（プログラミング）', '全国商業高等学校協会主催 情報処理検定試験（プログラミング部門）', '全商検定', '公益財団法人 全国商業高等学校協会', 'mint', 'アルゴリズムは、追いかけ方さえ分かれば怖くない。', '3級・2級はビジネス情報部門と共通の内容で、1級からプログラミング部門に分かれます。プログラムの動きを1行ずつ追う「トレース」と、探索・整列・集計といった定番アルゴリズムの理解が得点の中心です。考え方が身につけば、進学先や就職後の学習にもそのままつながります。', '[{"label":"実施回数","value":"年1回"},{"label":"級","value":"3級／2級（共通）／1級（プログラミング部門）"},{"label":"出題形式","value":"筆記＋実技"},{"label":"合格基準","value":"筆記・実技ともに規定の得点以上"}]'::jsonb, '["トレースを紙に書き出す手順を型にして、プログラムの動きを目で追えるように","探索・整列・集計など頻出アルゴリズムをパターンとして習得","配列や繰り返しでつまずく箇所を、変数の中身を1つずつ確認しながら解消","過去問を本番と同じ時間配分で解き、解き終わらない原因を特定","間違えた問題を分類し、同じ失点を繰り返さないための復習リストを作成"]'::jsonb, '1対1の個別指導の料金です。受験する級に合わせて選べます。', '[{"grade":"3級","price":"3,100","unit":"円 / 1時間"},{"grade":"2級","price":"3,200","unit":"円 / 1時間"},{"grade":"1級","price":"3,400","unit":"円 / 1時間"}]'::jsonb, '[]'::jsonb, '※ 受講回数やスケジュールは相談しながら決められます。詳しくは無料体験のときにご案内します。', '[{"problem":"プログラムを読んでも、動きがイメージできない","solution":"変数の値を表にして、1行ずつ書き換えながら追う練習をします。頭の中だけで考えるのをやめると、複雑な処理でも確実に追えるようになります。"},{"problem":"配列の添字が絡むと混乱してしまう","solution":"添字と中身を分けて図に書く方法を身につけます。どこがずれているかが目で見えるので、原因の特定が早くなります。"},{"problem":"アルゴリズムの問題だけ極端に点が取れない","solution":"出題される型は限られています。頻出パターンを分類し、「この形が来たらこう解く」という対応表を作って反復します。"}]'::jsonb),
  ('zensho-eiken', '英語検定', '全国商業高等学校協会主催 英語検定試験', '全商検定', '公益財団法人 全国商業高等学校協会', 'lemon', '英語は「検定の型」で解けば、ちゃんと点になる。', '商業高校生を対象にした英語の検定です。リスニングと筆記で構成され、ビジネスの場面を扱った英文が出題されます。出題の型が決まっているため、対策の順番を間違えなければ短期間でも得点を伸ばしやすく、進学の推薦や就職でも評価されやすい検定です。', '[{"label":"実施回数","value":"年2回"},{"label":"級","value":"3級／2級／1級"},{"label":"出題形式","value":"リスニング＋筆記"},{"label":"合格基準","value":"規定の得点以上"}]'::jsonb, '["大問ごとの解き方の型を決め、初見の問題でも手順どおりに処理できるように","頻出の単語・熟語を場面ごとにまとめ、使われ方とセットで記憶","リスニングは1日10分の継続メニューを組み、耳を慣らす","過去問を本番と同じ時間配分で解き、時間切れになる原因を特定","間違えた問題を分類し、同じ失点を繰り返さないための復習リストを作成"]'::jsonb, '1対1の個別指導の料金です。受験する級に合わせて選べます。', '[{"grade":"3級","price":"3,100","unit":"円 / 1時間"},{"grade":"2級","price":"3,200","unit":"円 / 1時間"},{"grade":"1級","price":"3,400","unit":"円 / 1時間"}]'::jsonb, '[]'::jsonb, '※ 受講回数やスケジュールは相談しながら決められます。詳しくは無料体験のときにご案内します。', '[{"problem":"単語は覚えたのに、長文になると読めない","solution":"1文ずつ主語と動詞を確認しながら読む練習に切り替えます。読み方の土台ができると、知らない単語があっても文の意味を推測できるようになります。"},{"problem":"リスニングが速くて追いつけない","solution":"先に設問と選択肢を読み、何を聞き取るかを決めてから聞く手順を徹底します。全部を聞き取ろうとしないことで、必要な情報を拾えるようになります。"},{"problem":"文法問題で毎回同じところを迷う","solution":"迷った問題を分類すると、つまずいている文法項目は数個に絞られます。そこだけを集中的に演習し、判断の根拠を言葉で説明できる状態にします。"}]'::jsonb),
  ('bunsho-sakusei', 'ビジネス文書実務検定', '全国商業高等学校協会主催 ビジネス文書実務検定試験', '全商検定', '公益財団法人 全国商業高等学校協会', 'sakura', '速さも正確さも、練習した分だけ確実に伸びる。', '文書作成ソフトの操作と、ビジネス文書の知識を測る検定です。一定時間の入力量を測る「速度部門」と、文書の作成・校正・知識を問う「ビジネス文書部門」で構成されます。積み上げた練習量がそのまま結果に出るため、計画的に続けられるかどうかが合否を分けます。', '[{"label":"実施回数","value":"年2回"},{"label":"級","value":"3級／2級／1級"},{"label":"部門","value":"速度部門／ビジネス文書部門"},{"label":"合格基準","value":"部門ごとに規定の基準以上"}]'::jsonb, '["検定日から逆算して、毎日続けられる分量のタイピング練習メニューを設計","打ち間違えの癖（特定のキー・変換ミス）を特定し、そこだけを重点練習","ビジネス文書のレイアウトのルールを型として覚え、減点箇所をつぶす","過去問を本番と同じ時間で解き、部門ごとに現在地を確認","間違えた問題を分類し、同じ失点を繰り返さないための復習リストを作成"]'::jsonb, '1対1の個別指導の料金です。受験する級に合わせて選べます。', '[{"grade":"3級","price":"3,100","unit":"円 / 1時間"},{"grade":"2級","price":"3,200","unit":"円 / 1時間"},{"grade":"1級","price":"3,400","unit":"円 / 1時間"}]'::jsonb, '[]'::jsonb, '※ 受講回数やスケジュールは相談しながら決められます。詳しくは無料体験のときにご案内します。', '[{"problem":"練習しているのに入力速度が上がらない","solution":"速度が止まる原因は、指の運び方か変換のどちらかにあることがほとんどです。入力の様子を見ながら原因を特定し、直す順番を決めて練習します。"},{"problem":"入力はできるが、ミスが多くて得点にならない","solution":"ミスした文字を記録すると、間違えるキーは決まっていることが分かります。速度を少し落として正確さを固めてから、もう一度上げていきます。"},{"problem":"文書の体裁で細かく減点される","solution":"余白・配置・記号の使い方など、減点されやすい箇所はパターン化できます。チェックリストを作り、提出前に必ず確認する習慣をつけます。"}]'::jsonb),
  ('dentaku-jitsumu', '珠算・電卓実務検定', '全国商業高等学校協会主催 珠算・電卓実務検定試験', '全商検定', '公益財団法人 全国商業高等学校協会', 'sky', '電卓は、指の置き方から変えると速くなる。', '計算の速さと正確さを測る検定です。乗算・除算・見取算などの「普通計算部門」と、利息や割引といった実務的な計算を扱う「ビジネス計算部門」で構成されます。電卓の操作に慣れることは簿記の得点にも直結するため、早いうちに取り組むほど効果の大きい検定です。', '[{"label":"実施回数","value":"年2回"},{"label":"級","value":"3級／2級／1級"},{"label":"部門","value":"普通計算部門／ビジネス計算部門"},{"label":"合格基準","value":"部門ごとに規定の基準以上"}]'::jsonb, '["電卓の持ち方・指の運び方・メモリー機能の使い方から見直す","乗算・除算・見取算それぞれの手順を型にして、反復で速度を上げる","ビジネス計算は公式を場面ごとに整理し、問題文から使う式を選べるように","時間を計った演習を繰り返し、本番と同じペースで解き切る感覚を身につける","間違えた問題を分類し、同じ失点を繰り返さないための復習リストを作成"]'::jsonb, '1対1の個別指導の料金です。受験する級に合わせて選べます。', '[{"grade":"3級","price":"3,100","unit":"円 / 1時間"},{"grade":"2級","price":"3,200","unit":"円 / 1時間"},{"grade":"1級","price":"3,400","unit":"円 / 1時間"}]'::jsonb, '[]'::jsonb, '※ 受講回数やスケジュールは相談しながら決められます。詳しくは無料体験のときにご案内します。', '[{"problem":"見取算の途中で桁を打ち間違えてしまう","solution":"数字の読み上げ方と目の動かし方を固定します。どこで視線が飛んでいるかを確認しながら、正確に打てる速度から段階的に上げていきます。"},{"problem":"ビジネス計算の公式がごちゃまぜになる","solution":"公式を丸暗記せず、「何を求める場面か」で分類して整理します。問題文のキーワードから使う式を選ぶ練習を重ねると、迷いがなくなります。"},{"problem":"時間内に最後まで解き終わらない","solution":"1問あたりの目標時間を決めて演習します。詰まったら飛ばす判断を練習しておくことで、取れる問題を確実に拾えるようになります。"}]'::jsonb)
on conflict (slug) do nothing;
